language "moriarty-sherlock-draft/1";
program P {
  fn inner(x: UInt): UInt { x + 1 }
  entry 10 + inner(3);
}

language "moriarty-sherlock-draft/1";
program P {
  fn fact(n: UInt): UInt { if n == 0 { 1 } else { n * fact(n - 1) } }
  entry fact(3);
}

language "moriarty-sherlock-draft/1";
program P {
  fn sum(xs: List): UInt { match xs { nil => 0, cons(h,t) => h + sum(t) } }
  entry sum(cons(2,cons(5,nil)));
}

language "moriarty-sherlock-draft/1";
program P {
  fn id(xs: List): List { xs }
  entry id(cons(1, cons(2, nil)));
}

language "moriarty-sherlock-draft/1";
program P {
  fn fold(t: Tree): UInt { match t { leaf(x) => x, branch(l, r) => fold(l) + fold(r) } }
  entry fold(branch(leaf(4), leaf(5)));
}

